function primeFactors(n){ n=Math.floor(Math.abs(n)); if(n<2) return []; var f=[]; var d=2; while(d*d<=n){var c=0;while(n%d===0){c++;n=n/d;}if(c)f.push([d,c]);d++;} if(n>1)f.push([n,1]); return f; }
function isPrime(n){ n=Math.floor(n); if(n<2)return false; if(n%2===0)return n===2; for(var d=3;d*d<=n;d+=2){if(n%d===0)return false;} return true; }
function numberOfDivisors(n){ var f=primeFactors(n); var t=1; for(var i=0;i<f.length;i++)t*=(f[i][1]+1); return t; }
function divisors(n){ n=Math.floor(Math.abs(n)); if(n<1)return []; var ds=[]; for(var i=1;i*i<=n;i++){ if(n%i===0){ ds.push(i); if(i!==n/i) ds.push(n/i); } } ds.sort(function(a,b){return a-b;}); return ds; }
var EXPORTS={primeFactors:primeFactors,isPrime:isPrime,numberOfDivisors:numberOfDivisors,divisors:divisors};


